public List<List<Integer>> subsets(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    int n = nums.length;
    int num_subsets = 1 << n;

    for (int i = 0; i < num_subsets; ++i) {
        List<Integer> subset = new ArrayList<>();
        for (int j = 0; j < n; ++j) {
            if ((i & (1 << j)) != 0) {
                subset.add(nums[j]);
            }
        }
        result.add(subset);
    }
    return result;
}
