public List<List<Integer>> pathSum(TreeNode root, int targetSum) {
    List<List<Integer>> ans = new ArrayList<>();
    List<Integer> current = new ArrayList<>();
    helper(root, targetSum, current, ans);
    return ans;
}

private void helper(TreeNode root, int targetSum, List<Integer> current, List<List<Integer>> ans) {
    if (root == null) return;
    current.add(root.val);
    if (root.left == null && root.right == null && targetSum == root.val) {
        ans.add(new ArrayList<>(current));
    }
    helper(root.left, targetSum - root.val, current, ans);
    helper(root.right, targetSum - root.val, current, ans);
    current.remove(current.size() - 1);
}
```

