    for (auto& p : prerequisites) {
        adjList[p[1]].push_back(p[0]);
        inDegree[p[0]]++;
    }

    queue<int> q;
    for (int i = 0; i < numCourses; i++) {
        if (inDegree[i] == 0) {
            q.push(i);
        }
    }

    vector<int> order;

    while (!q.empty()) {
        int curr = q.front();
        q.pop();
        order.push_back(curr);
        for (auto next : adjList[curr]) {
            if (--inDegree[next] == 0) {
                q.push(next);
            }
        }
    }

    return (order.size() == numCourses) ? order : vector<int>();
}
