public int[] singleNumber(int[] nums) {
    int xor_all = 0;
    for (int num : nums) {
        xor_all ^= num;
    }

    int bit = xor_all & -xor_all;
    int n1 = 0;
    int n2 = 0;
    for (int num : nums) {
        if ((num & bit) != 0) {
            n1 ^= num;
        } else {
            n2 ^= num;
        }
    }

    return new int[]{n1, n2};
}
