import java.util.*;

public class Solution {
    public List<String> generatePalindromes(String s) {
        List<String> result = new ArrayList<>();
        Map<Character, Integer> charCount = new HashMap<>();
        for (char c : s.toCharArray()) {
            charCount.put(c, charCount.getOrDefault(c, 0) + 1);
        }

        String midChar = "";
        List<Character> halfChars = new ArrayList<>();
        int numOdds = 0;
        for (Map.Entry<Character, Integer> entry : charCount.entrySet()) {
            if (entry.getValue() % 2 == 1) {
                numOdds++;
                midChar = String.valueOf(entry.getKey());
            }
            for (int i = 0; i < entry.getValue() / 2; i++) {
                halfChars.add(entry.getKey());
            }

            if (numOdds > 1) {
                return result;
            }
        }

        permute(0, halfChars, midChar, new ArrayList<>(), result);
        return result;
    }

    private void permute(int idx, List<Character> halfChars, String midChar, List<Character> current, List<String> result) {
        if (idx == halfChars.size()) {
            String firstHalf = "".valueOf(current.toArray(new Character[0]));
            result.add(firstHalf + midChar + new StringBuilder(firstHalf).reverse());
            return;
        }

        for (int i = 0; i < halfChars.size(); i++) {
            if (i > 0 && halfChars.get(i) == halfChars.get(i - 1)) {
                continue;
            }
            Character c = halfChars.remove(i);
            current.add(c);
            permute(idx + 1, halfChars, midChar, current, result);
            current.remove(current.size() - 1);
            halfChars.add(i, c);
        }
    }
}
```

    1. Count the occurrences of each character in the given string `s`.
2. If there are more than one odd counts for any character, there can't be a palindrome, so return an empty list.
3. Create two parts of the palindrome, `halfStr` and `midChar`. The `halfStr` will contain half of `s` divided by character counts, and `midChar` will contain the middle character if `s` has an odd length.
4. Generate all unique permutations of `halfStr`.
5. For each permutation of `halfStr`, concatenate it with `midChar` and its reverse to create a palindrome and add it to the result list.
6. Return the result list.

