function findItinerary(tickets) {
    const flights = {};
    const itinerary = [];

    for (const ticket of tickets) {
        if (!flights[ticket[0]]) {
            flights[ticket[0]] = [];
        }
        flights[ticket[0]].push(ticket[1]);
        flights[ticket[0]].sort((a, b) => b.localeCompare(a));
