private int depthSumHelper(List<?> nestedList, int depth) {
    int sum = 0;
    for (Object element : nestedList) {
        if (element instanceof Integer) {
            sum += (int) element * depth;
        } else {
            sum += depthSumHelper((List<?>) element, depth + 1);
        }
    }
    return sum;
}
