import java.util.HashMap;

public int lengthOfLongestSubstringKDistinct(String s, int k) {
    HashMap<Character, Integer> charCount = new HashMap<>();
    int left = 0, maxLength = 0;

    for (int right = 0; right < s.length(); ++right) {
        charCount.put(s.charAt(right), charCount.getOrDefault(s.charAt(right), 0) + 1);

        while (charCount.size() > k) {
            charCount.put(s.charAt(left), charCount.get(s.charAt(left)) - 1);
            if (charCount.get(s.charAt(left)) == 0) {
                charCount.remove(s.charAt(left));
            }
            left++;
        }

        maxLength = Math.max(maxLength, right - left + 1);
    }
    return maxLength;
}
```

    1. Create a hashmap to store character counts within the sliding window.
2. Initialize `left` and `maxLength` to zero.
3. Iterate through the string with a for loop:
