import java.util.*;

class SnakeGame {
    private int width, height, pos, score;
    private int[][] food;
    private LinkedList<int[]> snake;
    private Set<String> occupied;

    public SnakeGame(int width, int height, int[][] food) {
        this.width = width;
        this.height = height;
        this.food = food;
        pos = 0;
        score = 0;
        snake = new LinkedList<>();
        occupied = new HashSet<>();
        snake.add(new int[]{0, 0});
        occupied.add("0_0");
    }

    public int move(String direction) {
        int newX = snake.peekLast()[0] + dx.get(direction);
        int newY = snake.peekLast()[1] + dy.get(direction);

        if (newX < 0 || newX >= height || newY < 0 || newY >= width) {
            return -1;
        }

        int[] newHead = new int[]{newX, newY};
        int[] tail = snake.poll();

        if (pos < food.length && food[pos][0] == newX && food[pos][1] == newY) {
            score++;
            pos++;
        } else {
            occupied.remove(tail[0] + "_" + tail[1]);
        }

        if (occupied.contains(newX + "_" + newY)) {
            return -1;
        }

        snake.add(newHead);
        occupied.add(newX + "_" + newY);
        return score;
    }

    private static final Map<String, Integer> dx = Map.of("U", -1, "D", 1, "L", 0, "R", 0);
    private static final Map<String, Integer> dy = Map.of("U", 0, "D", 0, "L", -1, "R", 1);
}
```

    1. Initialize variables width, height, food, pos (food position), score, snake deque with initial position (0, 0), occupied set with initial position, dx and dy dictionary to update coordinate values based on given direction.
2. In the move method, calculate the next possible coordinates new_x and new_y using dx and dy dictionary.
3. Check if the new_x and new_y are out of the boundary, if yes then return -1 as it's a game over.
4. Check if the new position matches with food, if yes then update the score and increment the pos otherwise remove the tail block from the snake and occupied set.
5. If new_head is already in the occupied set, return -1, Because after moving the snake is colliding itself.
6. Otherwise, add the new_head in the snake deque and occupied set then return the current score.

