public int powmod(int a, int b) {
    if (b == 0) return 1;
    int res = powmod(a, b / 2);
    if (b % 2 == 0) return res * res % 1337;
    return res * res % 1337 * a % 1337;
}

public int superPow(int a, int[] b) {
    int n = 0;
    for (int bi : b) n = (n * 10 + bi) % 1140;
    return powmod(a % 1337, n + 1140);
}
```

