import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public List<int[]> pacificAtlantic(int[][] heights) {
    int m = heights.length;
    int n = heights[0].length;
    boolean[][] pacific = new boolean[m][n];
    boolean[][] atlantic = new boolean[m][n];

    for (int r = 0; r < m; ++r) {
        dfs(heights, r, 0, -1, pacific);
        dfs(heights, r, n - 1, -1, atlantic);
    }
    for (int c = 0; c < n; ++c) {
        dfs(heights, 0, c, -1, pacific);
        dfs(heights, m - 1, c, -1, atlantic);
    }
    List<int[]> result = new ArrayList<>();
    for (int r = 0; r < m; ++r) {
        for (int c = 0; c < n; ++c) {
            if (pacific[r][c] && atlantic[r][c]) {
                result.add(new int[]{r, c});
            }
        }
    }
    return result;
}

private void dfs(int[][] heights, int r, int c, int prevHeight, boolean[][] visited) {
    if (r < 0 || r >= heights.length || c < 0 || c >= heights[0].length) return;
    if (heights[r][c] >= prevHeight && !visited[r][c]) {
        visited[r][c] = true;
        dfs(heights, r - 1, c, heights[r][c], visited);
        dfs(heights, r + 1, c, heights[r][c], visited);
        dfs(heights, r, c - 1, heights[r][c], visited);
        dfs(heights, r, c + 1, heights[r][c], visited);
    }
}
```


    We use DFS to traverse the island, starting from the ocean borders. We create two separate matrices (`pacific` and `atlantic`) keeping track of which cells can flow water to the corresponding ocean. For each cell, we perform DFS in all 4 directions if the neighboring cell's height is less than or equal to the current cell's height.

After finishing the DFS search for both oceans, we iterate through the matrices to find the intersections (cells that can flow water to both oceans). If a cell can flow water to both oceans, we add its coordinates to the result list.

