        if root is None:
            return ""

        data = str(root.val) + " "
        for child in root.children:
            data += self.serialize(child)
        data += "# "
        return data

    def deserialize(self, data):
        def dfs(iter_data):
            val = next(iter_data)
            if val == "#":
                return None

            node = Node(int(val))
            while True:
                child = dfs(iter_data)
                if child is None:
                    break
                node.children.append(child)
            return node

        return dfs(iter(data.split()))

