public class AllOne {
    private HashMap<String, Integer> data;

    public AllOne() {
        data = new HashMap<String, Integer>();
    }

    public void inc(String key) {
        data.put(key, data.getOrDefault(key, 0) + 1);
    }

    public void dec(String key) {
        data.put(key, data.getOrDefault(key, 0) - 1);
        if (data.get(key) == 0) {
            data.remove(key);
        }
    }

