        if (data.isEmpty()) return "";
        return Collections.max(data.entrySet(), Map.Entry.comparingByValue()).getKey();
    }

    public String getMinKey() {
        if (data.isEmpty()) return "";
        return Collections.min(data.entrySet(), Map.Entry.comparingByValue()).getKey();
    }
}
