public int[] findRightInterval(int[][] intervals) {
    int[] res = new int[intervals.length];
    TreeMap<Integer, Integer> starts = new TreeMap<>();

    for(int i = 0; i < intervals.length; i++) {
        starts.put(intervals[i][0], i);
    }

    for(int i = 0; i < intervals.length; i++) {
