        key = ''.join(random.choices(self.alphabet, k=6))

        while key in self.url_map:
            key = ''.join(random.choices(self.alphabet, k=6))

        self.url_map[key] = longUrl
        return "http://tinyurl.com/" + key

    def decode(self, shortUrl: str) -> str:
        return self.url_map[shortUrl[-6:]]
