import java.util.*;
class Solution {
    public int[] cheapestJump(int[] coins, int maxJump) {
        int n = coins.length;
        int[] dp = new int[n];
        int[] parent = new int[n];
        Arrays.fill(dp, Integer.MAX_VALUE);
        Arrays.fill(parent, -1);
        dp[0] = coins[0];
        for (int i = 0; i < n; ++i) {
            if (coins[i] == -1) continue;
            for (int j = 1; j <= maxJump && i + j < n; ++j) {
                int next = i + j;
                int cost = coins[next] + dp[i];
