public boolean canSplit(int[] nums) {
    int[] freq = new int[20001], needed = new int[20001];
    for (int n : nums)
        freq[n]++;
    for (int n : nums) {
        if (freq[n] == 0) continue;
        if (needed[n - 1] == 0) {
            if (freq[n + 1] > 0 && freq[n + 2] > 0) {
                freq[n]--; freq[n + 1]--; freq[n + 2]--;
                needed[n + 2]++;
            } else return false;
        } else {
            freq[n]--; needed[n - 1]--;
            needed[n]++;
        }
    }
    return true;
}
```

