            right = q.front().second;
            q.pop();

            if (node->left) {
                q.push(std::make_pair(node->left, 2 * right));
            }
            if (node->right) {
                q.push(std::make_pair(node->right, 2 * right + 1));
            }
        }
        maxWidth = std::max(maxWidth, right - left + 1);
    }
    return maxWidth;
}
