public int numLightConfiguration(int n, int presses) {
    int[][] dp = new int[n + 1][presses + 1];
    dp[0][0] = 1;

    for (int i = 0; i <= n; ++i) {
        for (int j = 1; j <= presses; ++j) {
            dp[i][j] = dp[i][j - 1] * (i + 1) + (i > 0 ? dp[i - 1][j - 1] : 0);
        }
    }

    return dp[n][presses];
}
```

