        LinkedList<Pair> bucket = data[key % size];
        for (Pair pair : bucket) {
            if (pair.getKey() == key) {
                return pair.getValue();
            }
        }
        return -1;
    }

    public void remove(int key) {
        LinkedList<Pair> bucket = data[key % size];
        bucket.removeIf(pair -> pair.getKey() == key);
    }

