        if (prev.val <= insertVal && insertVal <= curr.val) {
            prev.next = new Node(insertVal, curr);
            inserted = true;
        } else if (prev.val > curr.val) {
            if (insertVal >= prev.val || insertVal <= curr.val) {
                prev.next = new Node(insertVal, curr);
                inserted = true;
