import java.util.Arrays;
import java.util.HashMap;
import java.util.Random;

class Solution {
    private HashMap<Integer, Integer> mapping;
    private int last;
    private Random random;

    public Solution(int n, int[] blacklist) {
        Arrays.sort(blacklist);
        mapping = new HashMap<>();
        int idx = 0;
        for (int i = 0; i < blacklist.length; ++i) {
            int black = blacklist[i];
            while (idx < black) {
                mapping.put(idx++, --n);
            }
            idx++;
            n--;
        }
        last = n;
        random = new Random();
    }

    public int pick() {
        int num = random.nextInt(last);
        return mapping.getOrDefault(num, num);
    }
}
```

    We create a mapping from the non-blacklisted range `[0, n - blacklist.size())` to the full available range `[0, n)`. For each non-blacklisted number `num`, the mapping contains the non-blacklisted number that corresponds to its position `num - blacklist[i]` in the full available range. We initialize the mapping by iterating over the sorted `blacklist`, and we pick a random integer in the non-blacklisted range and use the mapping to get the corresponding available number. To minimize the number of calls to the random function, we only call it once per `pick()` call. This ensures that any integer in the non-blacklisted range is equally likely to be returned.

