import java.util.ArrayList;
import java.util.HashSet;
import java.util.Set;

class Solution {
    private void dfs(int r, int c, int r0, int c0, int[][] grid, ArrayList<int[]> island){
        if (r >= 0 && c >= 0 && r < grid.length && c < grid[0].length && grid[r][c] == 1) {
            grid[r][c] = 0;
            island.add(new int[]{r - r0, c - c0});
            dfs(r + 1, c, r0, c0, grid, island);
            dfs(r - 1, c, r0, c0, grid, island);
            dfs(r, c + 1, r0, c0, grid, island);
            dfs(r, c - 1, r0, c0, grid, island);
        }
    }

    private String normalize(ArrayList<int[]> island) {
        ArrayList<String> ret = new ArrayList<>();
        for (int[] p : island) {
            int x = p[0];
            int y = p[1];
            ret.add(x + "," + y);
            ret.add(x + "," + -y);
            ret.add(-x + "," + y);
            ret.add(-x + "," + -y);
            ret.add(y + "," + x);
            ret.add(y + "," + -x);
            ret.add(-y + "," + x);
            ret.add(-y + "," + -x);
        }
        ret.sort(String::compareTo);
        return String.join(" ", ret);
    }

    public int numDistinctIslands(int[][] grid) {
        Set<String> distinctIslands = new HashSet<>();
        for (int r = 0; r < grid.length; ++r) {
            for (int c = 0; c < grid[r].length; ++c) {
                if (grid[r][c] == 1) {
                    ArrayList<int[]> island = new ArrayList<>();
                    dfs(r, c, r, c, grid, island);
                    distinctIslands.add(normalize(island));
                }
            }
        }
        return distinctIslands.size();
    }
}
```


    The algorithm uses DFS to traverse each island in the grid. For each island, it calculates its normalized form by considering all possible rotations and reflections. This normalized form is the "key" for this island. Then, the algorithm uses a set to count the number of distinct islands.

1. For each cell in the grid, if it's 1, run DFS and find the positions of the island.
2. Normalize the positions by comparing them to all possible rotations and reflections, and choosing the lexicographically SMALLEST of these forms. By this way, all the forms considered the same will have the same "key". This "key" is a sorted list of the positions.
3. Add the normalized positions to the set. Since sets only store unique items, we can count the number of distinct islands by counting the size of the set after iterating through the whole grid.

