import java.util.Stack;
import java.util.TreeSet;

class MaxStack {
    Stack<Integer> mainStack;
    TreeSet<Integer> maxSet;

    public MaxStack() {
        mainStack = new Stack<>();
        maxSet = new TreeSet<>();
    }

    public void push(int x) {
        mainStack.push(x);
        maxSet.add(x);
    }

    public int pop() {
        int top = mainStack.pop();
        maxSet.remove(top);
        return top;
    }

    public int top() {
        return mainStack.peek();
    }

    public int peekMax() {
        return maxSet.last();
    }

    public int popMax() {
        int max = maxSet.last();
        maxSet.remove(max);

        Stack<Integer> tempStack = new Stack<>();
        while (mainStack.peek() != max) {
            tempStack.push(mainStack.pop());
        }
        mainStack.pop();
        while (!tempStack.isEmpty()) {
            mainStack.push(tempStack.pop());
        }

        return max;
    }
}
```

    The algorithm uses two data structures, a main stack and a max set. The main stack is used to store the elements, and the max set is used to store the maximum elements in a sorted order. When an element is pushed onto the stack, it is added to the main stack and the max set. When the top element of the stack is removed, it is also removed from the max set. To find the maximum element, the last element of the max set is returned. To pop the maximum element, the algorithm first finds the maximum element in the list, removes it from the max set, and then removes it from the stack. If there are multiple maximum elements in the list, only the top-most one is removed. The time complexity for each `top` call is O(1) and for each `push`, `pop`, `peekMax`, and `popMax` call is O(logn).

