            if (expression.startsWith("add", start + 1)) {
                int first = start + 5;
                int[] second = new int[]{first};
                int value1 = calculate(expression, first, end, variables, second);
                int value2 = calculate(expression, second[0] + 1, end, variables, null);
                return value1 + value2;
