        std::string s = bottom.substr(i, 2);
        if (mapping.count(s) == 0) return false;
    }

    curr = "";
    for (int i = 0; i < bottom.size() - 1; ++i) {
        curr += mapping[bottom.substr(i, 2)][0];
    }

    return dfs(curr, curr, mapping);
}

