            if (digit == 2 || digit == 5 || digit == 6 || digit == 9) {
                isDifferentAfterRotation = true;
            }
            num /= 10;
        }
        if (isValidAfterRotation && isDifferentAfterRotation) {
            count++;
        }
    }
    return count;
}
