    List<int[]> onesImg1 = new ArrayList<>();
    List<int[]> onesImg2 = new ArrayList<>();
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (img1[i][j] == 1) onesImg1.add(new int[]{i, j});
