import java.util.List;
import java.util.ArrayList;
import java.util.Map;
import java.util.HashMap;
import java.util.Set;
import java.util.HashSet;

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int x) { val = x; }
}

public List<Integer> findNodesAtDistanceK(TreeNode root, int targetVal, int k) {
    if (k < 0) return new ArrayList<>();
    Map<TreeNode, TreeNode> parentMap = new HashMap<>();
    Set<TreeNode> visited = new HashSet<>();
    TreeNode targetNode = initializeParentMap(root, null, targetVal, parentMap);

    List<Integer> result = new ArrayList<>();
    findNodesAtDistanceKHelper(targetNode, k, visited, parentMap, result);
    return result;
}

private TreeNode initializeParentMap(TreeNode node, TreeNode parent, int targetVal, Map<TreeNode, TreeNode> parentMap) {
    if (node == null) return null;
    if (node.val == targetVal) return node;
    parentMap.put(node, parent);
    TreeNode left = initializeParentMap(node.left, node, targetVal, parentMap);
    TreeNode right = initializeParentMap(node.right, node, targetVal, parentMap);
    return left != null ? left : right;
}

private void findNodesAtDistanceKHelper(TreeNode node, int k, Set<TreeNode> visited, Map<TreeNode, TreeNode> parentMap, List<Integer> result) {
    if (node == null || visited.contains(node)) return;
    visited.add(node);
    if (k == 0) {
        result.add(node.val);
        return;
    }

    findNodesAtDistanceKHelper(node.left, k-1, visited, parentMap, result);
    findNodesAtDistanceKHelper(node.right, k-1, visited, parentMap, result);
    findNodesAtDistanceKHelper(parentMap.get(node), k-1, visited, parentMap, result);
}
```


    This algorithm first creates a mapping of each node to its parent. This is done through the `initializeParentMap()` function which also finds the `targetNode` as it traverses the tree. When running the function, the parent map is built, mapping a node to its parent, and the target node with the required value is found. Once we have the targetNode and parentMap, we start the search for nodes at distance k using DFS approach starting from the targetNode. We use the `findNodesAtDistanceKHelper()` function that takes the current node, distance k, visited set (to avoid infinite looping), and the parentMap. If k is 0, we add the node's value into the result array. If not, we continue DFS for the left and right children, and also the parent (using the parentMap), with the updated k value (k-1). Finally, the result array containing values of nodes at distance k is returned.

