import java.util.HashSet;
import java.util.Set;

class Solution {
    public int robotSim(int[] commands, int[][] obstacles) {
        int[] dx = {0, 1, 0, -1};
        int[] dy = {1, 0, -1, 0};
        int x = 0, y = 0, di = 0;

        Set<Long> obstacleSet = new HashSet<>();
        for (int[] obstacle : obstacles) {
            long ox = (long) obstacle[0] + 30000;
            long oy = (long) obstacle[1] + 30000;
            obstacleSet.add((ox << 16) + oy);
        }

        int ans = 0;
        for (int cmd : commands) {
            if (cmd == -2) {
                di = (di + 3) % 4;
            } else if (cmd == -1) {
                di = (di + 1) % 4;
            } else {
                for (int k = 0; k < cmd; k++) {
                    int nx = x + dx[di];
                    int ny = y + dy[di];
                    long code = (((long) nx + 30000) << 16) + ((long) ny + 30000);

                    if (!obstacleSet.contains(code)) {
                        x = nx;
                        y = ny;
                        ans = Math.max(ans, x * x + y * y);
                    }
                }
            }
        }

        return ans;
    }
}
```


    The algorithm consists of simulating the robot's movements for each command, while keeping track of its position, direction, and obstacles. If the command is to turn left or right, the direction is updated accordingly. If the command is to move straight, the robot moves one unit at a time in its current direction unless it is blocked by an obstacle. We use a set to store the obstacle locations (In Javascript, we use bitwise operations to encode the location in a single number). 

We compute the Euclidean square distance (x^2 + y^2) every time the robot moves successfully and update the maximum distance found so far. After executing all commands, the maximum distance is returned.

