class Solution {
    private int[][] rects;
    private ArrayList<Integer> areas;
    private int totalArea;
    private Random random;

    public Solution(int[][] rects) {
        this.rects = rects;
        areas = new ArrayList<Integer>();
        totalArea = 0;
        for (int[] rect : rects) {
            int area = (rect[2] - rect[0] + 1) * (rect[3] - rect[1] + 1);
            totalArea += area;
            areas.add(totalArea);
        }
        random = new Random();
    }

