    int n = grid.length;
    int top = 0, front = 0, side = 0;
    for (int i = 0; i < n; i++) {
        int maxFront = 0, maxSide = 0;
        for (int j = 0; j < n; j++) {
            if (grid[i][j] > 0) {
                top++;
