public int partitionDisjoint(int[] nums) {
    int leftMax = nums[0], globalMax = nums[0], leftLength = 1;
    for (int i = 1; i < nums.length; ++i) {
        if (nums[i] < leftMax) {
            leftMax = globalMax;
            leftLength = i + 1;
        } else {
            globalMax = Math.max(globalMax, nums[i]);
        }
    }
    return leftLength;
