import java.util.LinkedList;
import java.util.Queue;

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int x) { val = x; }
}

class CBTInserter {
    TreeNode root;
    Queue<TreeNode> q;

    public CBTInserter(TreeNode root) {
        this.root = root;
        q = new LinkedList<>();
        q.add(root);
        while (true) {
            TreeNode node = q.peek();
            if (node.left == null || node.right == null) break;
            q.add(node.left);
            q.add(node.right);
            q.poll();
        }
    }

    public int insert(int v) {
        TreeNode newNode = new TreeNode(v);
        TreeNode parentNode = q.peek();
        if (parentNode.left == null) {
            parentNode.left = newNode;
        } else {
            parentNode.right = newNode;
            q.add(parentNode.left);
            q.add(parentNode.right);
            q.poll();
        }
        return parentNode.val;
    }

    public TreeNode get_root() {
        return root;
    }
}
```


    The algorithm starts by initializing a queue with the given root node. At each step, it checks if the front node from the queue has an empty left or right child. If so, the algorithm breaks from the loop as it found the first node with an empty child.

To insert a new node, it creates a new node with the provided value and checks if the left child of the front node from the queue is empty. If so, it assigns the new node as the left child. Otherwise, it assigns the new node as the right child, push both left and right children of the front node to the queue, and removes the front node from the queue. It returns the value of the parent node.

The get_root method returns the root of the tree.

