#include <vector>
#include <deque>
#include <algorithm>

std::vector<int> deckRevealedIncreasing(std::vector<int>& deck) {
    int n = deck.size();
    std::deque<int> index;
    for (int i = 0; i < n; ++i)
        index.push_back(i);

    std::vector<int> ans(n);
    std::sort(deck.begin(), deck.end());

    for (int card : deck) {
        ans[index.front()] = card;
        index.pop_front();
        if (!index.empty()) {
            index.push_back(index.front());
            index.pop_front();
        }
    }

    return ans;
}
