public boolean canReorderArray(int[] arr) {
    HashMap<Integer, Integer> count = new HashMap<>();
    for (int n : arr) {
        count.put(n, count.getOrDefault(n, 0) + 1);
    }
    Arrays.sort(arr);
    for (int x : arr) {
        if (count.get(x) == 0) {
            continue;
        }
        if (count.getOrDefault(2 * x, 0) > 0) {
            count.put(x, count.get(x) - 1);
            count.put(2 * x, count.get(2 * x) - 1);
        } else {
            return false;
        }
    }
    return true;
}
```

