public int[] sumEvenAfterQueries(int[] nums, int[][] queries) {
    int[] answer = new int[queries.length];
    int even_sum = 0;

    for (int num : nums) {
        if (num % 2 == 0) {
            even_sum += num;
        }
    }

    for (int i = 0; i < queries.length; i++) {
        int value = queries[i][0];
        int index = queries[i][1];

        if (nums[index] % 2 == 0) {
            even_sum -= nums[index];
        }
        nums[index] += value;
        if (nums[index] % 2 == 0) {
            even_sum += nums[index];
        }
        answer[i] = even_sum;
    }

    return answer;
}
```


