        return { node: null, depth: 0 };
    }

    let leftLCA = findLCAUtil(root.left);
    let rightLCA = findLCAUtil(root.right);

    if (leftLCA.depth > rightLCA.depth) {
        leftLCA.depth++;
        return leftLCA;
    } else if (leftLCA.depth < rightLCA.depth) {
        rightLCA.depth++;
        return rightLCA;
    } else {
        return { node: root, depth: leftLCA.depth + 1 };
    }
}

function lcaDeepestLeaves(root) {
    return findLCAUtil(root).node;
}
