        max_sum[0] = Math.max(max_sum[0], arr1[i] + arr2[i] + i);
        max_sum[1] = Math.max(max_sum[1], arr1[i] - arr2[i] + i);
        max_sum[2] = Math.max(max_sum[2], -arr1[i] + arr2[i] + i);
        max_sum[3] = Math.max(max_sum[3], -arr1[i] - arr2[i] + i);
