        result = Math.max(result, max_sum[0] - arr1[i] - arr2[i] - i);
        result = Math.max(result, max_sum[1] - arr1[i] + arr2[i] - i);
        result = Math.max(result, max_sum[2] + arr1[i] - arr2[i] - i);
        result = Math.max(result, max_sum[3] + arr1[i] + arr2[i] - i);
    }

    return result;
}
