class FileSystem {
    private final HashMap<String, Integer> pathMap;

    public FileSystem() {
        pathMap = new HashMap<>();
    }

    public boolean createPath(String path, int value) {
        if (pathMap.containsKey(path)) return false;
        String parentPath = path.substring(0, path.lastIndexOf('/'));
        if (!parentPath.isEmpty() && !pathMap.containsKey(parentPath)) return false;
