    for (const [neighbor, edgeProb] of graph[node]) {
      const newProb = prob * edgeProb;
      if (newProb > maxProb[neighbor]) {
        maxProb[neighbor] = newProb;
        pq.push([newProb, neighbor]);

        // Re-sort the queue, so it stays a max heap.
        pq.sort(([a], [b]) => b - a);
