    maxGold = Math.max(maxGold, getMaximumGoldHelper(grid, x - 1, y, m, n));
    maxGold = Math.max(maxGold, getMaximumGoldHelper(grid, x, y + 1, m, n));
    maxGold = Math.max(maxGold, getMaximumGoldHelper(grid, x, y - 1, m, n));

    grid[x][y] = originalGold;
    return maxGold + originalGold;
}
