        if (!mod[1].empty()) {
            mod[1].pop_back();
        } else {
            mod[2].pop_back();
            mod[2].pop_back();
        }
    } else {
        if (!mod[2].empty()) {
            mod[2].pop_back();
        } else {
            mod[1].pop_back();
            mod[1].pop_back();
        }
    }

    std::string result;
    for (int i = 0; i < 3; ++i) {
        for (int digit : mod[i]) {
            result += std::to_string(digit);
        }
    }

    std::sort(result.rbegin(), result.rend());
    if (result.empty() || result[0] == '0') {
        return "0";
    }

    return result;
