    private int[] dfs(TreeNode node) {
        if (node == null) 
            return new int[]{1, 0, Integer.MAX_VALUE, Integer.MIN_VALUE};

        int[] l = dfs(node.left);
        int[] r = dfs(node.right);

        if (l[0] == 0 || r[0] == 0 || node.val <= l[3] || node.val >= r[2]) 
            return new int[4];

        int currSum = node.val + l[1] + r[1];
        maxSum = Math.max(maxSum, currSum);

        return new int[]{1, currSum, Math.min(node.val, l[2]), Math.max(node.val, r[3])};
    }
}
```


