                    result.append(entities.get(entity));
                } else {
                    result.append(entity);
                }
                inEntity = false;
                currentEntity = new StringBuilder();
            }
        } else {
            if (c == '&') {
                inEntity = true;
                currentEntity.append(c);
            } else {
                result.append(c);
            }
        }
    }

    return result.toString();
}
