public int maxSubstringOccurrences(String s, int k) {
    int n = s.length(), res = 0;
    HashMap<Character, Integer> freq = new HashMap<>();
    for (int i = 0; i < n; ++i) {
        freq.put(s.charAt(i), freq.getOrDefault(s.charAt(i), 0) + 1);
        if (freq.size() <= k) {
