        freq_map[c]++;
    }

    while (!freq_map.empty()) {
        for (auto it = freq_map.begin(); it != freq_map.end();) {
            result += it->first;
            it->second--;

            if (it->second == 0) {
                it = freq_map.erase(it);
            } else {
                ++it;
            }
        }

        for (auto it = freq_map.rbegin(); it != freq_map.rend();) {
            auto next = std::next(it).base();
            result += it->first;
            it->second--;

            if (it->second == 0) {
                freq_map.erase(next);
            }
            it = std::reverse_iterator(next);
        }
    }

    return result;
}
