import java.util.Arrays;

public int maxEvents(int[][] events) {
    Arrays.sort(events, (a, b) -> a[1] - b[1]);

    int count = 0;
    int lastDay = -1;

    for (int[] event : events) {
        if (event[0] > lastDay) {
            count++;
            lastDay = event[1];
        }
    }

