import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public String rankTeams(String[] votes) {
        int teams = votes[0].length();
        int[][] ranks = new int[26][teams];

        for (String vote : votes) {
            for (int i = 0; i < teams; ++i) {
                ranks[vote.charAt(i) - 'A'][i]++;
            }
        }

        Character[] result = new Character[teams];
        for (int i = 0; i < teams; ++i) {
            result[i] = votes[0].charAt(i);
        }

        Arrays.sort(result, new Comparator<Character>() {
            public int compare(Character a, Character b) {
                for (int i = 0; i < teams; ++i) {
                    if (ranks[a - 'A'][i] != ranks[b - 'A'][i]) {
                        return ranks[b - 'A'][i] - ranks[a - 'A'][i];
                    }
                }
                return a.compareTo(b);
            }
        });

        StringBuilder sb = new StringBuilder();
        for (Character ch : result) {
            sb.append(ch);
        }
        return sb.toString();
    }
}
```


    1. Count the rank positions of each team in a 2D array (index 0-25 represent the team letter). The array stores the votes count for each position.
2. Sort the given team letters in lexicographical order, so it can be later used for the stable sort.
3. For each position and its votes count, sort the teams based on the number of votes they received in descending order. If two or more teams tie, use the next position's votes count, and so on. If they tie after considering all positions, sort them based on their team letter.
4. Convert the sorted team letters back into a string.

