  const engineers = efficiency.map((e, i) => [e, speed[i]]);
  engineers.sort((a, b) => b[0] - a[0]);

  let sum = 0, result = 0;
  const minHeap = new MinHeap();
  for (const [e, s] of engineers) {
    if (minHeap.size() >= k) {
      sum -= minHeap.poll();
    }
    minHeap.offer(s);
    sum += s;
    result = Math.max(result, e * sum);
  }

  return result % 1000000007;
