public int countLargestGroup(int n) {
    int[] freq = new int[37];
    int maxGroupSize = 0, maxGroupCount = 0;

    for (int i = 1; i <= n; i++) {
        int sum = 0, num = i;
        while (num != 0) {
            sum += num % 10;
            num = num / 10;
        }
        freq[sum]++;
        maxGroupSize = Math.max(maxGroupSize, freq[sum]);
    }

    for (int i = 0; i < 37; i++) {
        if (freq[i] == maxGroupSize) {
            maxGroupCount++;
        }
    }

    return maxGroupCount;
}
