        for (Iterator<Integer> it = remainingColors.iterator(); it.hasNext();) {
            int color = it.next();
            int[] bounds = colorBounds.get(color);
            boolean contained = true;
            for (int i = bounds[0]; i <= bounds[2] && contained; ++i) {
                for (int j = bounds[1]; j <= bounds[3]; ++j) {
