public int minDifference(int[] nums) {
    int size = nums.length;
    if (size < 5) return 0;

    Arrays.sort(nums);

    return Math.min(Math.min(nums[size-1] - nums[3], nums[size-2] - nums[2]), Math.min(nums[size-3] - nums[1], nums[size-4] - nums[0]));
}
