        dp[0][i] = count[i][target.charCodeAt(0) - 'a'.charCodeAt(0)];
    }

    for (let i = 1; i < m; i++) {
        for (let j = 0; j < n; j++) {
            for (let k = 0; k < n; k++) {
                dp[i][j] = (dp[i][j] + dp[i-1][k] * count[j][target.charCodeAt(i) - 'a'.charCodeAt(0)]) % mod;
            }
        }
    }

    return dp[m-1].reduce((acc, val) => (acc + val) % mod, 0);
}
