public int minNumOperations(int[] nums) {
    int result = 0;
    int[] highestBit = new int[32];
    for (int num : nums) {
        for (int j = 0; j < 32; j++) {
            if ((num & (1 << j)) != 0) {
                highestBit[j]++;
            }
        }
    }
    for (int count : highestBit) {
        result = Math.max(result, count);
    }
    return result + 31;
}
