public int minimumEffort(int[][] tasks) {
    Arrays.sort(tasks, (a, b) -> (b[1] - b[0]) - (a[1] - a[0]));
    int ans = 0, sum = 0;
    for (int[] task : tasks) {
        ans = Math.max(ans, sum + task[1]);
        sum += task[0];
    }
    return ans;
}
