function minCost(n, cuts) {
    cuts.push(0);
    cuts.push(n);
    cuts.sort((a, b) => a - b);
    const size = cuts.length;
    const dp = Array.from({ length: size }, () => Array(size).fill(0));

    for (let len = 2; len < size; len++) {
        for (let i = 0; i < size - len; i++) {
            const j = i + len;
            dp[i][j] = Infinity;
            for (let k = i + 1; k < j; k++) {
                dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k][j] + cuts[j] - cuts[i]);
            }
        }
    }

    return dp[0][size - 1];
}
