public boolean containsPattern(int[] arr, int m, int k) {
    int n = arr.length;
    if (m * k > n) return false;

    for (int i = 0; i + m * k <= n; i++) {
        boolean patternFound = true;
        for (int j = 0; j < m; j++) {
            for (int l = 1; l < k; l++) {
                if (arr[i + j] != arr[i + j + l * m]) {
                    patternFound = false;
                    break;
                }
            }
            if (!patternFound) break;
        }
        if (patternFound) return true;
    }
    return false;
}
```

