import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public List<Boolean> checkArithmeticSubarrays(int[] nums, int[] l, int[] r) {
    List<Boolean> results = new ArrayList<>();
    for(int i = 0; i < l.length; i++) {
        int[] subarray = Arrays.copyOfRange(nums, l[i], r[i] + 1);
        Arrays.sort(subarray);
        boolean is_arithmetic = true;
        int diff = subarray[1] - subarray[0];
        for(int j = 1; j < subarray.length - 1; j++) {
            if(subarray[j + 1] - subarray[j] != diff) {
                is_arithmetic = false;
                break;
            }
        }
        results.add(is_arithmetic);
    }
    return results;
}
```


    1. For each element `i` in arrays `l` and `r`, create a subarray from `nums` using the range `[l[i], r[i]]`.
2. Sort the subarray.
3. Check if the subarray is an arithmetic sequence, by iterating through the subarray and making sure the difference between consecutive elements is the same.
4. If the subarray is an arithmetic sequence, add `true` to the result array, otherwise, add `false`.
