        ptr = 1;
        data = new HashMap<>();
    }

    public List<String> insert(int idKey, String value) {
        data.put(idKey, value);
        List<String> result = new ArrayList<>();
        while (data.containsKey(ptr)) {
            result.add(data.get(ptr));
            ptr++;
        }
        return result;
    }
}
