public int countBalls(int lowLimit, int highLimit) {
    int[] boxCounts = new int[46];
    for(int i = lowLimit; i <= highLimit; i++) {
        int boxNumber = 0;
        int num = i;
        while(num != 0) {
            boxNumber += num % 10;
            num /= 10;
        }
        boxCounts[boxNumber]++;
    }
    return Arrays.stream(boxCounts).max().orElse(0);
}
