public int subsetXORSum(int[] nums) {
    int ans = 0, n = nums.length, max_val = 1 << n;
    for (int i = 1; i < max_val; i++) {
        int xor_total = 0;
        for (int j = 0; j < n; j++) {
            if ((i & (1 << j)) > 0) {
                xor_total ^= nums[j];
            }
        }
        ans += xor_total;
    }
    return ans;
}
