int numDifferentIntegers(std::string word) {
    for (char &c : word) {
        if (c < '0' || c > '9') {
            c = ' ';
        }
    }
    std::istringstream iss(word);
    std::string num;
    std::unordered_set<std::string> uniqueNums;
