int minSpaceWastedKResizing(std::vector<int>& nums, int k) {
    int n = nums.size();
    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(k + 1, std::numeric_limits<int>::max() / 3));
    std::vector<int> sum(n + 1, 0);
    dp[0][0] = 0;
    for (int i = 1; i <= n; i++) {
        sum[i] = sum[i - 1] + nums[i - 1];
        int max_val = nums[i - 1];
        for (int j = i - 1; j >= 0; j--) {
            max_val = std::max(max_val, nums[j]);
            int waste = max_val * (i - j) - (sum[i] - sum[j]);
            for (int c = 0; c < k; c++) {
                dp[i][c + 1] = std::min(dp[i][c + 1], dp[j][c] + waste);
            }
        }
    }
    return dp[n][k];
}
```

