std::vector<int> longestObstacleCourse(std::vector<int>& obstacles) {
    std::vector<int> dp;
    std::vector<int> ans(obstacles.size());

    for (int i = 0; i < obstacles.size(); ++i) {
        auto it = std::lower_bound(dp.begin(), dp.end(), obstacles[i]);
        ans[i] = std::distance(dp.begin(), it) + 1;
        if (it == dp.end()) {
            dp.push_back(obstacles[i]);
        } else {
            *it = obstacles[i];
        }
    }

    return ans;
}
