public String maxValue(String n, int x) {
    boolean is_negative = n.charAt(0) == '-';
    int pos = is_negative ? 1 : 0;

    while (pos < n.length()) {
        if (is_negative && n.charAt(pos) - '0' > x || !is_negative && n.charAt(pos) - '0' < x) {
            break;
        }
        pos++;
    }

    return n.substring(0, pos) + Integer.toString(x) + n.substring(pos);
}
