public int minMoves(int n) {
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 1;

    for (int i = 2; i <= n; i++) {
        dp[i] = i;
        for (int x = 1; x < i; x++) {
            int broken = x - 1;
            int unbroken = i - x;
            dp[i] = Math.min(dp[i], 1 + Math.max(dp[broken], dp[unbroken]));
        }
    }

    return dp[n];
}
```

