    let steps = 0;

    while (q.length > 0) {
        const size = q.length;
        for (let i = 0; i < size; ++i) {
            const [x, y] = q.shift();
            if ((x === 0 || x === m - 1 || y === 0 || y === n - 1) && (x !== entrance[0] || y !== entrance[1]))
                return steps;

            for (const dir of directions) {
                const xx = x + dir[0];
                const yy = y + dir[1];
                if (xx >= 0 && xx < m && yy >= 0 && yy < n && maze[xx][yy] === '.') {
                    maze[xx][yy] = '+';
                    q.push([xx, yy]);
                }
            }
        }
        ++steps;
    }

    return -1;
}
```


