public ListNode sortedList(ListNode head) {
    if (head == null || head.next == null) return head;

    ListNode prev = head;
    ListNode cur = head.next;

    while (cur != null) {
        if (cur.val < prev.val) {
            prev.next = cur.next;
            cur.next = head;
            head = cur;
            cur = prev;
        } else {
            prev = cur;
        }
        cur = cur.next;
    }
    return head;
}
