            } else {
                this.dir = (this.dir + 1) % 4;
                num++; // Retry the step
            }
        }
    }

    getPos() {
        return [this.x, this.y];
    }

    getDir() {
        const directions = ["East", "North", "West", "South"];
        return directions[this.dir];
    }
}
