public int maxMatrixSum(int[][] matrix) {
    int n = matrix.length;
    int minValue = Integer.MAX_VALUE, negativeCount = 0, sum = 0;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            sum += Math.abs(matrix[i][j]);
            minValue = Math.min(minValue, Math.abs(matrix[i][j]));
            if (matrix[i][j] < 0) {
                negativeCount++;
            }
        }
    }

    if (negativeCount % 2 == 0) {
        return sum;
    } else {
        return sum - 2 * minValue;
    }
}
