public int countPairsWithDifferenceK(int[] nums, int k) {
    Map<Integer, Integer> freqMap = new HashMap<>();
    int count = 0;

    for (int num : nums) {
        count += freqMap.getOrDefault(num - k, 0) + freqMap.getOrDefault(num + k, 0);
        freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);
    }

    return count;
}
