public int[] findNoOfInstructions(int n, int[] startPos, String s) {
    int[] answer = new int[s.length()];
    int x = startPos[0];
    int y = startPos[1];

    for (int i = 0; i < s.length(); ++i) {
        int cnt = 0;
        int cx = x;
        int cy = y;
        for (int j = i; j < s.length(); ++j) {
            char step = s.charAt(j);
            if (step == 'L') {
                if (cy == 0) break;
                cy -= 1;
            }
            else if (step == 'R') {
                if (cy == n - 1) break;
                cy += 1;
            }
            else if (step == 'U') {
                if (cx == 0) break;
                cx -= 1;
            }
            else {
                if (cx == n - 1) break;
                cx += 1;
            }
            cnt++;
            if (j == s.length() - 1) break;
        }
        answer[i] = cnt;
    }

    return answer;
}
```


