    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (board[i][j] == word.charAt(0)) {
                if (checkWord(board, word, i, j, 0, 1) || checkWord(board, word, i, j, 1, 0))
                    return true;
            }
        }
    }
    return false;
}

public boolean checkWord(char[][] board, String word, int i, int j, int di, int dj) {
    int m = board.length, n = board[0].length;
    for (int k = 0; k < word.length(); ++k, i += di, j += dj) {
        if (i < 0 || i >= m || j < 0 || j >= n)
            return false;
        if (k == 0 || k == word.length() - 1)
            if (board[i][j] != word.charAt(k) && board[i][j] != ' ')
                return false;
        if (k > 0 && k < word.length() - 1)
            if (board[i][j] != word.charAt(k) && board[i][j] != ' ' && board[i][j] != '#')
                return false;
    }
    return true;
}
