        if ("aeiou".indexOf(word.charAt(i)) != -1) {
            vowels.clear();
            for (int j = i; j < n; j++) {
                if ("aeiou".indexOf(word.charAt(j)) != -1) {
                    vowels.add(word.charAt(j));
