int minimumOperations(String current, String correct) {
    int ch = Integer.parseInt(current.substring(0, 2)), cm = Integer.parseInt(current.substring(3));
    int th = Integer.parseInt(correct.substring(0,2)), tm = Integer.parseInt(correct.substring(3));
    int ct = ch * 60 + cm, tt = th * 60 + tm;

    int operations = 0;
    while (ct < tt) {
        if (tt - ct >= 60)
            ct += 60;
        else if (tt - ct >= 15)
            ct += 15;
        else if (tt - ct >= 5)
            ct += 5;
        else
            ct += 1;

        operations++;
    }
    return operations;
}
