        for (int j = 0; j < n; j++) {
            if (bank[i].charAt(j) == '1') {
                for (int k = j + 1; k < n && bank[i].charAt(k) != '1'; k++) {
                    beams += bank[i].charAt(k) == '0' ? 1 : 0;
