public int earliestBloomingDay(int[] plantTime, int[] growTime) {
    Integer[] bloomTime = new Integer[plantTime.length];
    for (int i = 0; i < plantTime.length; i++) {
        bloomTime[i] = plantTime[i] + growTime[i];
    }
    Arrays.sort(bloomTime);
    int earliestDay = 0;
