int minNumberOfBeansToRemove(const std::vector<int>& beans) {
    std::unordered_map<int, int> count;
    for (int bean : beans) {
        count[bean]++;
    }

    int min_remove = beans.size();
    for (const auto& item : count) {
        int remove = 0;
        for (const auto& other : count) {
            if (other.first != item.first) {
                remove += other.second * std::max(0, other.first - item.first);
            }
        }
        min_remove = std::min(min_remove, remove);
    }

    return min_remove;
