class TextEditor {
    string text;
    int cursor;
public:
    TextEditor() {
        text = "";
        cursor = 0;
    }

    void addText(string newText) {
        text.insert(cursor, newText);
        cursor += newText.size();
    }

    int deleteText(int k) {
        int deleted = min(k, cursor);
        text.erase(cursor - deleted, deleted);
        cursor -= deleted;
        return deleted;
    }

    string cursorLeft(int k) {
        cursor -= min(k, cursor);
        return text.substr(max(0, cursor - 10), min(10, cursor));
    }

    string cursorRight(int k) {
        cursor += min(k, (int)text.size() - cursor);
        return text.substr(max(0, cursor - 10), min(10, cursor));
    }
};
