vector<int> kthSmallestIndex(vector<string>& nums, vector<vector<int>>& queries) {
    vector<int> answer;
    vector<pair<int, int>> indices(nums.size());
    for (size_t i = 0; i < nums.size(); ++i) {
        indices[i] = {stoi(nums[i]), i};
    }

    for (auto& query : queries) {
        auto k = query[0];
        auto trim = query[1];
        for (size_t i = 0; i < nums.size(); ++i) {
            indices[i].first = stoi(nums[i].substr(nums[i].size() - trim));
        }
        sort(indices.begin(), indices.end());
        answer.push_back(indices[k - 1].second);
    }

    return answer;
}
