    let correctMins = parseInt(correct.substring(0, 2)) * 60 + parseInt(correct.substring(3, 5));
    if (currentMins > correctMins) correctMins += 24 * 60;

    let diff = correctMins - currentMins;
    let count = Math.floor(diff / 60) + Math.floor((diff % 60) / 15) + Math.floor(((diff % 60) % 15) / 5) + Math.floor((((diff % 60) % 15) % 5));

    return count;
}
