int maxCoveredRows(std::vector<std::vector<int>>& matrix, int numSelect) {
    int m = matrix.size();
    int n = matrix[0].size();
    int max_covered = 0;

    for (int i = 0; i < (1 << n); ++i) {
        if (__builtin_popcount(i) == numSelect) {
            int covered = 0;
            for (int row = 0; row < m; ++row) {
                for (int col = 0; col < n; ++col) {
                    if ((matrix[row][col] == 1) && (i & (1 << col))) {
