public int longestAlphabeticalContinuousSubstring(String s) {
    int maxLength = 1, currentLength = 1;
    for (int i = 1; i < s.length(); ++i) {
        if (s.charAt(i) == s.charAt(i - 1) + 1) {
            ++currentLength;
