    let total_sum = nums.reduce((sum, num) => sum + num, 0);
    let n = nums.length;
    let mod = 1000000007;

    if (total_sum < k * 2) {
        return 0;
    }

    let dp = new Array(n + 1).fill(1);

    for (let i = 1; i <= k - 1; i++) {
        for (let j = n - 1; j >= 1; j--) {
            dp[j] = (dp[j] * j + dp[j - 1]) % mod;
        }
    }

    let result = 0;

    for (let i = 0; i < n - 1; i++) {
        total_sum -= nums[i];
        if (total_sum >= k) {
            result = (result + dp[i + 1]) % mod;
        }
    }

    return result;
}
```

