        time[leftTop.second][2] += time[leftTop.second][3] + time[leftTop.second][0] + time[leftTop.second][1];
        right.push({leftTop.first + time[leftTop.second][1], leftTop.second});
        n--;
    }

    int lastMoment = -1;
    while (!right.empty()) {
        lastMoment = max(lastMoment, time[right.top().second][2]);
        right.pop();
    }
    return lastMoment;
}
