    int n = edges.size() + 1;
    std::vector<int> in_degree(n, 0);
    std::unordered_set<int> guess_parents;

    for (const auto& guess : guesses) {
        guess_parents.insert(guess[0]);
    }

    for (const auto& edge : edges) {
        in_degree[edge[1]]++;
    }

    int possible_roots = 0;
    for (int i = 0; i < n; ++i) {
        if (in_degree[i] == 0) {
            if (k == 0 || guess_parents.find(i) != guess_parents.end()) {
                possible_roots++;
            }
        } else if (in_degree[i] == 1 && guesses.size() - k < in_degree[i]) {
            possible_roots++;
        }
    }
    return possible_roots;
}
